                            seen[ny][nx] = True; q.append((ny, nx))
                if len(cells) == 1:
                    singles.add(cells[0])
    for (i, j) in singles:
        nb = [grid[y][x] for y, x in ((i-1,j),(i+1,j),(i,j-1),(i,j+1))
